import {
  GenMapping,
  maybeAddMapping,
  setSourceContent,
  allMappings,
  toEncodedMap,
  toDecodedMap,
} from "@jridgewell/gen-mapping";

import type {
  EncodedSourceMap,
  DecodedSourceMap,
  Mapping,
} from "@jridgewell/gen-mapping";

import {
  type SourceMapInput,
  originalPositionFor,
  TraceMap,
} from "@jridgewell/trace-mapping";

/**
 * Build a sourcemap.
 */

export default class SourceMap {
  private _map: GenMapping;
  private _rawMappings: Mapping[] | undefined;
  private _sourceFileName: string | undefined;

  // Any real line is > 0, so init to 0 is fine.
  private _lastGenLine = 0;
  private _lastSourceLine = 0;

  // Source columns can be 0, but we ony check in unison with sourceLine, which
  // inits to an impossible value. So init to 0 is fine.
  private _lastSourceColumn = 0;

  public _inputMap: TraceMap;

  constructor(
    opts: {
      sourceFileName?: string;
      sourceRoot?: string;
      inputSourceMap?: SourceMapInput;
    },
    code: string | { [sourceFileName: string]: string },
  ) {
    const map = (this._map = new GenMapping({ sourceRoot: opts.sourceRoot }));
    this._rawMappings = undefined;

    const rawFileName = opts.sourceFileName;
    if (rawFileName == null) {
      this._sourceFileName = undefined;
    } else if (typeof rawFileName !== "string") {
      this._sourceFileName = (rawFileName as string).replace(/\\/g, "/");
    } else if (rawFileName.length === 0) {
      this._sourceFileName = rawFileName;
    } else {
      const fileSegments: string[] = [];
      let fileSegment = "";
      for (let index = 0; index < rawFileName.length; index++) {
        const charCode = rawFileName.charCodeAt(index);
        if (charCode === 92) {
          fileSegments.push(fileSegment);
          fileSegment = "";
        } else if (charCode === 47) {
          fileSegments.push(fileSegment);
          fileSegment = "";
        } else {
          fileSegment += rawFileName.charAt(index);
        }
      }
      fileSegments.push(fileSegment);
      let normalizedFileName = "";
      for (let index = 0; index < fileSegments.length; index++) {
        if (index > 0) {
          normalizedFileName += "/";
        }
        normalizedFileName += fileSegments[index];
      }
      this._sourceFileName = normalizedFileName;
    }

    const inputSourceMap = opts.inputSourceMap;
    if (inputSourceMap) {
      if (typeof inputSourceMap === "string") {
        this._inputMap = new TraceMap(inputSourceMap);
      } else {
        this._inputMap = new TraceMap(inputSourceMap);
      }

      const resolvedSources = this._inputMap.resolvedSources;
      if (resolvedSources.length) {
        for (let i = 0; i < resolvedSources.length; i++) {
          setSourceContent(
            map,
            resolvedSources[i],
            this._inputMap.sourcesContent[i],
          );
        }
      }
    }

    if (typeof code === "string") {
      if (!opts.inputSourceMap) {
        const generatedMap = map as GenMapping & {
          _sources: {
            array: string[];
            _indexes: { [key: string]: number | undefined };
          };
          _sourcesContent: Array<string | null | undefined>;
        };
        const generatedSources = generatedMap._sources;
        const generatedContents = generatedMap._sourcesContent;
        const sourceName = this._sourceFileName;
        const sourceIndexes = generatedSources._indexes;
        const existingIndex = sourceIndexes[sourceName as string];
        if (existingIndex !== undefined) {
          generatedContents[existingIndex] = code;
        } else {
          const nextIndex = generatedSources.array.push(sourceName as string) - 1;
          sourceIndexes[sourceName as string] = nextIndex;
          generatedContents[nextIndex] = code;
        }
      }
    } else if (typeof code === "object") {
      const sourceNames = Object.keys(code);
      const generatedMap = map as GenMapping & {
        _sources: {
          array: string[];
          _indexes: { [key: string]: number | undefined };
        };
        _sourcesContent: Array<string | null | undefined>;
      };
      const generatedSources = generatedMap._sources;
      const generatedContents = generatedMap._sourcesContent;
      for (let nameIndex = 0; nameIndex < sourceNames.length; nameIndex++) {
        const sourceFileName = sourceNames[nameIndex];
        const sourceContent = code[sourceFileName];
        let normalizedSource = sourceFileName;
        if (sourceFileName.length !== 0) {
          const sourceSegments: string[] = [];
          let sourceSegment = "";
          for (let index = 0; index < sourceFileName.length; index++) {
            const charCode = sourceFileName.charCodeAt(index);
            if (charCode === 92) {
              sourceSegments.push(sourceSegment);
              sourceSegment = "";
            } else if (charCode === 47) {
              sourceSegments.push(sourceSegment);
              sourceSegment = "";
            } else {
              sourceSegment += sourceFileName.charAt(index);
            }
          }
          sourceSegments.push(sourceSegment);
          normalizedSource = "";
          for (let index = 0; index < sourceSegments.length; index++) {
            if (index > 0) {
              normalizedSource += "/";
            }
            normalizedSource += sourceSegments[index];
          }
        }
        const sourceIndexes = generatedSources._indexes;
        const existingIndex = sourceIndexes[normalizedSource];
        if (existingIndex !== undefined) {
          generatedContents[existingIndex] = sourceContent;
        } else {
          const nextIndex = generatedSources.array.push(normalizedSource) - 1;
          sourceIndexes[normalizedSource] = nextIndex;
          generatedContents[nextIndex] = sourceContent;
        }
      }
    }
  }

  /**
   * Get the sourcemap.
   */
  get(): EncodedSourceMap {
    return toEncodedMap(this._map);
  }

  getDecoded(): DecodedSourceMap {
    return toDecodedMap(this._map);
  }

  getRawMappings(): Mapping[] {
    return (this._rawMappings ||= allMappings(this._map));
  }

  /**
   * Mark the current generated position with a source position. May also be passed null line/column
   * values to insert a mapping to nothing.
   */

  mark(
    generated: { line: number; column: number },
    line: number,
    column: number,
    identifierName?: string | null,
    identifierNamePos?: { line: number; column: number },
    filename?: string | null,
  ) {
    this._rawMappings = undefined;

    let originalMapping: {
      source: string | null;
      name?: string | null;
      line: number | null;
      column: number | null;
    };

    if (line != null) {
      if (this._inputMap) {
        // This is the lookup for this mark
        originalMapping = originalPositionFor(this._inputMap, {
          line,
          column,
        });

        // If the we found a name, nothing else needs to be done
        // Maybe we're marking a `(` and the input map already had a name attached there,
        // or we're marking a `(` and the sourcemap spanned a `foo(`,
        // or we're marking an identifier, etc.
        if (!originalMapping.name && identifierNamePos) {
          // We're trying to mark a `(` (as that's the only thing that provides
          // an identifierNamePos currently), and we the AST had an identifier attached.
          // Lookup it's original name.
          const originalIdentifierMapping = originalPositionFor(
            this._inputMap,
            identifierNamePos,
          );
          if (originalIdentifierMapping.name) {
            identifierName = originalIdentifierMapping.name;
          }
        }
      } else {
        originalMapping = {
          source: filename?.replace(/\\/g, "/") || this._sourceFileName,
          line: line,
          column: column,
        };
      }
    }

    maybeAddMapping(this._map, {
      name: identifierName,
      generated,
      source: originalMapping?.source,
      original: originalMapping,
    });
  }
}

